select
teacherSubject.*,
s.subject_name
from teacher_subject teacherSubject
left join subject s on s.id = teacherSubject.subject_id

    and teacherSubject.id = #{id}
    and teacherSubject.teacher_id = #{teacherId}
    and teacherSubject.subject_id = #{subjectId}
    and teacherSubject.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from teacher_subject teacherSubject

    and teacherSubject.id = #{id}
    and teacherSubject.teacher_id = #{teacherId}
    and teacherSubject.subject_id = #{subjectId}
    and teacherSubject.create_time = #{createTime}
